OFFBOX_ALLOW_XLARGE=1 OFFBOX_BACKEND=server offbox run --bg --size xlarge --git --no-fallback --pull build/card-gate.log --pull build/card-gate.rc --pull build/card-summary.txt --pull build/full-gate.log --pull build/full-gate.rc --pull build/full-summary.txt --step 'mkdir -p build && git rev-parse HEAD && sha256sum scripts/tests/test_parallel_check.py && source scripts/env.sh && npm ci --offline --ignore-scripts' --step 'rc=0; TORS_GATE=card ./scripts/check.sh >build/card-gate.log 2>&1 || rc=$?; echo "$rc" >build/card-gate.rc; cp build/check-summary.txt build/card-summary.txt; tail -12 build/card-gate.log; exit "$rc"' --step 'rc=0; bash scripts/check.sh >build/full-gate.log 2>&1 || rc=$?; echo "$rc" >build/full-gate.rc; cp build/check-summary.txt build/full-summary.txt; tail -12 build/full-gate.log; exit "$rc"'